INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(295121, 20998, 3018, '<td valign="top">Wow! Awesome image.  This trick has been used several times in DPC, but yours is very good.</td>', 'Wow! Awesome image.  This trick has been used several times in DPC, but yours is very good.', '2003-05-12 01:09:58.000000', NULL, 1),
(295124, 21085, 6870, '<td valign="top">Stunning. Having the girls'' backs remind us of the color challenge. Lots of emotion in this shot make the colors seem to symbolize the emotions and  joy of these young girls. Just super work!</td>', 'Stunning. Having the girls'' backs remind us of the color challenge. Lots of emotion in this shot make the colors seem to symbolize the emotions and  joy of these young girls. Just super work!', '2003-05-12 01:11:07.000000', NULL, 1),
(295125, 21170, 6870, '<td valign="top">Nice macro. Great balance between all three colors. And white... Very nice shot!</td>', 'Nice macro. Great balance between all three colors. And white... Very nice shot!', '2003-05-12 01:12:15.000000', NULL, 1),
(295126, 21136, 2923, '<td valign="top">a bit overly saturated.</td>', 'a bit overly saturated.', '2003-05-12 01:12:34.000000', NULL, 1),
(295127, 21112, 6870, '<td valign="top">Wonderful lighting and tones. Yellow seems an afterthought, though. Very striking image! Nice work.</td>', 'Wonderful lighting and tones. Yellow seems an afterthought, though. Very striking image! Nice work.', '2003-05-12 01:13:03.000000', NULL, 1),
(295130, 20967, 6870, '<td valign="top">Wonderful framing for the child! colors seem just a little \"washed.\"</td>', 'Wonderful framing for the child! colors seem just a little \"washed.\"', '2003-05-12 01:14:15.000000', NULL, 1),
(295132, 21115, 6870, '<td valign="top">That is one expensive knife! Great shot though I''d like to see the whole frame move down a bit so the peppers are closer to the top and the knife is a little higher, too. But that''s a small matter. Excellent focus and DOF. Wonderful lighting and colors!</td>', 'That is one expensive knife! Great shot though I''d like to see the whole frame move down a bit so the peppers are closer to the top and the knife is a little higher, too. But that''s a small matter. Excellent focus and DOF. Wonderful lighting and colors!', '2003-05-12 01:15:58.000000', NULL, 1),
(295136, 21143, 2923, '<td valign="top">The blue is saturated to the point it starts to clip.......</td>', 'The blue is saturated to the point it starts to clip.......', '2003-05-12 01:18:33.000000', NULL, 1),
(295139, 21203, 4493, '<td valign="top">This is very well lit and saturated. A little more blue to the left of the hat and above the pegs would really make this a 10+ shot! -danny</td>', 'This is very well lit and saturated. A little more blue to the left of the hat and above the pegs would really make this a 10+ shot! -danny', '2003-05-12 01:20:17.000000', NULL, 1),
(295145, 21197, 6900, '<td valign="top">Lemme be the first of "I don''t get it"s .. What IS that?  *keeps looking* No I have no idea what I''m looking at...</td>', 'Lemme be the first of "I don''t get it"s .. What IS that?  *keeps looking* No I have no idea what I''m looking at...', '2003-05-12 01:25:38.000000', NULL, 1),
(295146, 20998, 6900, '<td valign="top">Unbelivably excellent.  This one caught my eye in thumbs and is just as good in full size.  I like that you split them down the stems as well.  10.</td>', 'Unbelivably excellent.  This one caught my eye in thumbs and is just as good in full size.  I like that you split them down the stems as well.  10.', '2003-05-12 01:27:38.000000', NULL, 1),
(295147, 21144, 6900, '<td valign="top">Beautiful composition.  I dislike your lighting - looks top-down.  What is it sitting on?  A tee?</td>', 'Beautiful composition.  I dislike your lighting - looks top-down.  What is it sitting on?  A tee?', '2003-05-12 01:30:31.000000', NULL, 1),
(295148, 20626, 1717, '<td valign="top">wow!  what a creative shot!  the colors are beautiful and nicely saturated.  well done!!</td>', 'wow!  what a creative shot!  the colors are beautiful and nicely saturated.  well done!!', '2003-05-12 01:31:11.000000', NULL, 1),
(295151, 21189, 7920, '<td valign="top">I love how the colors mix to form secondary colors. Nicely done!  ;)</td>', 'I love how the colors mix to form secondary colors. Nicely done!  ;)', '2003-05-12 01:31:54.000000', NULL, 1),
(295152, 20851, 6900, '<td valign="top">Good shot - the reflection is a tad bit distracting in the red - so are the scratches.  Good idea, but with such a flat bg, I''m not sure I like it.</td>', 'Good shot - the reflection is a tad bit distracting in the red - so are the scratches.  Good idea, but with such a flat bg, I''m not sure I like it.', '2003-05-12 01:32:09.000000', NULL, 1),
(295153, 21136, 6900, '<td valign="top">Oh nice!!!!!!!!!  I love this shot!  10+  I have tried pouring liquid shots - they are NOT easy - congrats on a great shot.</td>', 'Oh nice!!!!!!!!!  I love this shot!  10+  I have tried pouring liquid shots - they are NOT easy - congrats on a great shot.', '2003-05-12 01:33:05.000000', NULL, 1),
(295154, 20671, 6870, '<td valign="top">Looks like a prison camp--except they look so happy and jovial all in red! So an interesting juxtaposition that makes me think a while...</td>', 'Looks like a prison camp--except they look so happy and jovial all in red! So an interesting juxtaposition that makes me think a while...', '2003-05-12 01:34:28.000000', NULL, 1),
(295157, 20950, 6870, '<td valign="top">White usually stands for purity in the flag. What does yellow stand for? Nice lines and contrasts here. The fold in the middle works well.</td>', 'White usually stands for purity in the flag. What does yellow stand for? Nice lines and contrasts here. The fold in the middle works well.', '2003-05-12 01:35:20.000000', NULL, 1),
(295161, 21084, 6900, '<td valign="top">We all have to do one once, eh?  Nice job - what''s the yellow though?</td>', 'We all have to do one once, eh?  Nice job - what''s the yellow though?', '2003-05-12 01:47:35.000000', NULL, 1),
(295163, 21115, 6900, '<td valign="top">Funny! But unnatural!  I like the inclusion of the knife - that blue pepper scares me.</td>', 'Funny! But unnatural!  I like the inclusion of the knife - that blue pepper scares me.', '2003-05-12 01:48:34.000000', NULL, 1),
(295164, 21089, 7504, '<td valign="top">I love the stark colors against the green leaves, it has a surreal feel to it.  Very nice!</td>', 'I love the stark colors against the green leaves, it has a surreal feel to it.  Very nice!', '2003-05-12 01:50:34.000000', NULL, 1),
(295165, 21206, 772, '<td valign="top">I believe that sharper focus in this scene would have worked nicely...</td>', 'I believe that sharper focus in this scene would have worked nicely...', '2003-05-12 01:53:27.000000', NULL, 1),
