(295167, 21115, 772, '<td valign="top">interesing image for sure... the color change on the green pepper is bleeding over into your yellow pepper below the stem and making it look ''icky'' around the stem...</td>', 'interesing image for sure... the color change on the green pepper is bleeding over into your yellow pepper below the stem and making it look ''icky'' around the stem...', '2003-05-12 01:56:29.000000', NULL, 1),
(295177, 20986, 6870, '<td valign="top">Nice light, nice lines, nice colors, nice point of view. Dang it! I just can''t complain about anything here! 10</td>', 'Nice light, nice lines, nice colors, nice point of view. Dang it! I just can''t complain about anything here! 10', '2003-05-12 02:05:24.000000', NULL, 1),
(295178, 20997, 6870, '<td valign="top">Wonderful abstract. The title leaves me clueless, but the lines, colors and lighting here really pique my interest!</td>', 'Wonderful abstract. The title leaves me clueless, but the lines, colors and lighting here really pique my interest!', '2003-05-12 02:06:08.000000', NULL, 1),
