(295503, 21108, 3607, '<td valign="top">focus seems soft and lighting is okay, but a little too dark (or at least unevenly applied) for my taste.</td>', 'focus seems soft and lighting is okay, but a little too dark (or at least unevenly applied) for my taste.', '2003-05-12 11:30:58.000000', NULL, 1),
(295505, 20671, 7758, '<td valign="top">wow, looks like nobody bothered to check who was wearing red that day.... how embarrassing! Great shot and right on topic.... good luck, Todd.</td>', 'wow, looks like nobody bothered to check who was wearing red that day.... how embarrassing! Great shot and right on topic.... good luck, Todd.', '2003-05-12 11:32:03.000000', NULL, 1),
(295506, 20626, 3607, '<td valign="top">very nicely done.  only suggestion would be if you tried the shot with more space on the left and right instead of a portrait shot, where the negative space would serve as a contrast to the colors and help us focus on them w/out them becoming/dominating the photo as you did above.</td>', 'very nicely done.  only suggestion would be if you tried the shot with more space on the left and right instead of a portrait shot, where the negative space would serve as a contrast to the colors and help us focus on them w/out them becoming/dominating the photo as you did above.', '2003-05-12 11:32:25.000000', NULL, 1),
(295507, 21207, 3607, '<td valign="top">very nice.  i like the texture and color contrast of the wood versus the streamers.  the colors and lighting look great, and the composition is nice too.</td>', 'very nice.  i like the texture and color contrast of the wood versus the streamers.  the colors and lighting look great, and the composition is nice too.', '2003-05-12 11:33:17.000000', NULL, 1),
(295508, 21086, 5391, '<td valign="top">Cute.  Nice arrangement and composition.  The colors all match each other very well, also, which pulls the whole thing together well.</td>', 'Cute.  Nice arrangement and composition.  The colors all match each other very well, also, which pulls the whole thing together well.', '2003-05-12 11:33:53.000000', NULL, 1),
(295509, 20719, 8563, '<td valign="top">Majestic! Lighting on the yellow is unique</td>', 'Majestic! Lighting on the yellow is unique', '2003-05-12 11:34:11.000000', NULL, 1),
(295510, 21221, 3607, '<td valign="top">nice setup and choice of subject.  lighting looks a bit strange with the box seeming very bright but the ribbons seeming a little dark, esp. on top, but that''s just a nit, overall i like it very much.</td>', 'nice setup and choice of subject.  lighting looks a bit strange with the box seeming very bright but the ribbons seeming a little dark, esp. on top, but that''s just a nit, overall i like it very much.', '2003-05-12 11:34:11.000000', NULL, 1),
(295511, 20671, 3607, '<td valign="top">very interesting photo.  are their collars yellow?  two suggestions would be 1) take the photo from the right side so their faces are towards the sun and would not be half in shadow, and 2) it is effective in its own way - having the kids corralled in a barbed wire fence makes a strong photo, but people in general might find the image too strong for them.</td>', 'very interesting photo.  are their collars yellow?  two suggestions would be 1) take the photo from the right side so their faces are towards the sun and would not be half in shadow, and 2) it is effective in its own way - having the kids corralled in a barbed wire fence makes a strong photo, but people in general might find the image too strong for them.', '2003-05-12 11:36:28.000000', NULL, 1),
(295515, 21089, 3607, '<td valign="top">wow.  where did you take this.  very nice and effective.  great color, focus, composition, perspective.  top photo this week.</td>', 'wow.  where did you take this.  very nice and effective.  great color, focus, composition, perspective.  top photo this week.', '2003-05-12 11:37:46.000000', NULL, 1),
(295516, 21152, 7758, '<td valign="top">Great effect and good strong imagery... watch your verticals..... i think more saturation would have really made this stand out.... good luck, Todd.</td>', 'Great effect and good strong imagery... watch your verticals..... i think more saturation would have really made this stand out.... good luck, Todd.', '2003-05-12 11:37:48.000000', NULL, 1),
(295517, 21115, 7504, '<td valign="top">I love this image.  Very bright and beautiful colors, I just wish the knife wasn''t cut off on the bottom, but I gave it a 9.</td>', 'I love this image.  Very bright and beautiful colors, I just wish the knife wasn''t cut off on the bottom, but I gave it a 9.', '2003-05-12 11:39:14.000000', NULL, 1),
(295518, 20967, 7504, '<td valign="top">I love this image, all the circles are very interesting, and she''s so happy, it can''t help but make me happy too!  9</td>', 'I love this image, all the circles are very interesting, and she''s so happy, it can''t help but make me happy too!  9', '2003-05-12 11:39:57.000000', NULL, 1),
(295519, 20948, 7504, '<td valign="top">I really like this image, although it is a bit dark for my taste, the circles are interesting and the color good.  8<br/></td>', 'I really like this image, although it is a bit dark for my taste, the circles are interesting and the color good.  8', '2003-05-12 11:40:36.000000', NULL, 1),
(295520, 20980, 3607, '<td valign="top">interesting setup.  the colors look good, i like the contrast w/the b&amp;w at the bottom of the photo.  i don''t see why you needed the glass (empty at that) in there.</td>', 'interesting setup.  the colors look good, i like the contrast w/the b&w at the bottom of the photo.  i don''t see why you needed the glass (empty at that) in there.', '2003-05-12 11:40:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(295521, 21004, 7504, '<td valign="top">This is so nice, I love the colors and the blue background.  8</td>', 'This is so nice, I love the colors and the blue background.  8', '2003-05-12 11:41:12.000000', NULL, 1),
(295523, 21203, 7504, '<td valign="top">I like this a lot.  Very simple and well composed.  Nice color and contrast! 9</td>', 'I like this a lot.  Very simple and well composed.  Nice color and contrast! 9', '2003-05-12 11:41:52.000000', NULL, 1),
(295524, 21197, 772, '<td valign="top">interresting abstract theme, but something is a bit odd... as I look at this, I am expecting a two dimensional shot but the depth of field/focus seems to go from sharp to soft moving up the frame... it just seems odd...</td>', 'interresting abstract theme, but something is a bit odd... as I look at this, I am expecting a two dimensional shot but the depth of field/focus seems to go from sharp to soft moving up the frame... it just seems odd...', '2003-05-12 11:42:16.000000', NULL, 1),
(295527, 21016, 772, '<td valign="top">meets the challenge, but just doesn''t draw my interest in the subject...</td>', 'meets the challenge, but just doesn''t draw my interest in the subject...', '2003-05-12 11:43:08.000000', NULL, 1),
(295530, 21086, 772, '<td valign="top">I think this image is ok overall, but the border is too loud and it is competing for attenion.  Borders should be supportive of your subject and not distracting from it.</td>', 'I think this image is ok overall, but the border is too loud and it is competing for attenion.  Borders should be supportive of your subject and not distracting from it.', '2003-05-12 11:44:12.000000', NULL, 1),
(295531, 21083, 772, '<td valign="top">interesting composition... it looks almost as if it''s painted :)</td>', 'interesting composition... it looks almost as if it''s painted :)', '2003-05-12 11:44:59.000000', NULL, 1),
(295534, 21215, 5391, '<td valign="top">Very cute!  Shows you were really looking at things.  Great colors - I assume you used a polarizing filter to achieve the beautiful blue sky.  Nice work.  8</td>', 'Very cute!  Shows you were really looking at things.  Great colors - I assume you used a polarizing filter to achieve the beautiful blue sky.  Nice work.  8', '2003-05-12 11:45:08.000000', NULL, 1),
(295535, 21123, 3607, '<td valign="top">neat objects, but a little dark and dull (ie: better lighting and a boost in saturation would have added more zing to the image).</td>', 'neat objects, but a little dark and dull (ie: better lighting and a boost in saturation would have added more zing to the image).', '2003-05-12 11:45:40.000000', NULL, 1),
(295536, 21219, 772, '<td valign="top">meets the challenge, but the theme of ''primary'' colors doesn''t seem to dominate the theme...</td>', 'meets the challenge, but the theme of ''primary'' colors doesn''t seem to dominate the theme...', '2003-05-12 11:45:48.000000', NULL, 1),
(295538, 21092, 3607, '<td valign="top">nice find, i like the framing of the other playground in the background.  lighting is just okay - i wish you could have found an angle that didn''t have some shadows crossing the lit parts.  overall, however, its very fun (but no kids?)</td>', 'nice find, i like the framing of the other playground in the background.  lighting is just okay - i wish you could have found an angle that didn''t have some shadows crossing the lit parts.  overall, however, its very fun (but no kids?)', '2003-05-12 11:47:02.000000', NULL, 1),
(295540, 21173, 3607, '<td valign="top">a little soft in focus and i think a plainer background would have helped out as well.  i think the cropping and perspective could have been less tight which would have allowed the object to add more as the current photo doesn''t allow us all to fully identify what it is.</td>', 'a little soft in focus and i think a plainer background would have helped out as well.  i think the cropping and perspective could have been less tight which would have allowed the object to add more as the current photo doesn''t allow us all to fully identify what it is.', '2003-05-12 11:49:35.000000', NULL, 1),
(295542, 21185, 3607, '<td valign="top">nicely composed and executed, although i think the lipstick marks look more like (red) charcol/pencil rubbings than lipstick (might have considered a real kiss imprint).  good lighting.</td>', 'nicely composed and executed, although i think the lipstick marks look more like (red) charcol/pencil rubbings than lipstick (might have considered a real kiss imprint).  good lighting.', '2003-05-12 11:51:02.000000', NULL, 1),
(295543, 20996, 3607, '<td valign="top">just don''t do them all at once.  very creative idea and nice frame.  the lighting is just okay and the colors look a little dull, however, and could have benefitted from a boost in saturation to give them more zing.  a lower angle might have made the perspective more interesting as well.</td>', 'just don''t do them all at once.  very creative idea and nice frame.  the lighting is just okay and the colors look a little dull, however, and could have benefitted from a boost in saturation to give them more zing.  a lower angle might have made the perspective more interesting as well.', '2003-05-12 11:52:16.000000', NULL, 1),
(295547, 21130, 7743, '<td valign="top">Too bad there weren''t more clouds, otherwise interesting approach to this challenge.</td>', 'Too bad there weren''t more clouds, otherwise interesting approach to this challenge.', '2003-05-12 11:53:49.000000', NULL, 1),
(295553, 21152, 6661, '<td valign="top">Nice composition. The shadows add another element to the colour theme. Well done.</td>', 'Nice composition. The shadows add another element to the colour theme. Well done.', '2003-05-12 11:58:21.000000', NULL, 1),
(295562, 20671, 2764, '<td valign="top">zoom in - there''s too much going on here.</td>', 'zoom in - there''s too much going on here.', '2003-05-12 12:08:10.000000', NULL, 1),
(295564, 20998, 5391, '<td valign="top">This is one of those shots where I say to myself, "DARN!  I wish I''d thought of that."  Congrats.  Nice work.  I bet this will do well.  I really like the use of two glasses.  8</td>', 'This is one of those shots where I say to myself, "DARN!  I wish I''d thought of that."  Congrats.  Nice work.  I bet this will do well.  I really like the use of two glasses.  8', '2003-05-12 12:09:12.000000', NULL, 1),
(295565, 20769, 2764, '<td valign="top">chop down the tree??</td>', 'chop down the tree??', '2003-05-12 12:09:29.000000', NULL, 1),
(295566, 21143, 5266, '<td valign="top">The blue rose is creepy - did you do that yourself?  I really like your idea here - very nice lighting &amp; composition</td>', 'The blue rose is creepy - did you do that yourself?  I really like your idea here - very nice lighting & composition', '2003-05-12 12:09:56.000000', NULL, 1),
(295570, 21202, 772, '<td valign="top">i think this is an interesting composition... I''m not sure why you chose to have the flag in the shadows though... It seems like the colors would be much more dominant with some more light...</td>', 'i think this is an interesting composition... I''m not sure why you chose to have the flag in the shadows though... It seems like the colors would be much more dominant with some more light...', '2003-05-12 12:12:15.000000', NULL, 1),
(295573, 21123, 772, '<td valign="top">very interesting shapes on these flowers... i like the diagonal composition as well...</td>', 'very interesting shapes on these flowers... i like the diagonal composition as well...', '2003-05-12 12:13:14.000000', NULL, 1),
(295583, 21062, 327, '<td valign="top">Nice composition, creative.</td>', 'Nice composition, creative.', '2003-05-12 12:21:01.000000', NULL, 1),
(295584, 21206, 2764, '<td valign="top">too much stuff competing for attention - simplify it.  I''l take away the candles and put the  second ball back in the box</td>', 'too much stuff competing for attention - simplify it.  I''l take away the candles and put the  second ball back in the box', '2003-05-12 12:21:59.000000', NULL, 1),
(295585, 21143, 7543, '<td valign="top">The blue color is kind of weird for my eyes</td>', 'The blue color is kind of weird for my eyes', '2003-05-12 12:22:22.000000', NULL, 1),
(295588, 21103, 7543, '<td valign="top">Cool setup, I''m not quite getting what I''m looking at, but that''s half the fun. The blue one could of have had more contrast to the sky. Like it</td>', 'Cool setup, I''m not quite getting what I''m looking at, but that''s half the fun. The blue one could of have had more contrast to the sky. Like it', '2003-05-12 12:24:44.000000', NULL, 1),
(295590, 21223, 2764, '<td valign="top">Needs a better background, this one competes with the image</td>', 'Needs a better background, this one competes with the image', '2003-05-12 12:25:28.000000', NULL, 1),
(295593, 21219, 2764, '<td valign="top">how about a really tight crop since you lost the top of the head - do you need the hand at all?  draw attention to the mouth</td>', 'how about a really tight crop since you lost the top of the head - do you need the hand at all?  draw attention to the mouth', '2003-05-12 12:28:35.000000', NULL, 1),
(295596, 21212, 7628, '<td valign="top">I like how bold and simple the composition is - like the colors.  Wish the lids weren''t in there too - they complicate things unecesarily.</td>', 'I like how bold and simple the composition is - like the colors.  Wish the lids weren''t in there too - they complicate things unecesarily.', '2003-05-12 12:29:00.000000', NULL, 1),
(295597, 21130, 7628, '<td valign="top">Interesting place to try to find primaries  - but the colors are too pale, and the composition too random.  Perhaps a bolder sunset sky would work better?</td>', 'Interesting place to try to find primaries  - but the colors are too pale, and the composition too random.  Perhaps a bolder sunset sky would work better?', '2003-05-12 12:31:06.000000', NULL, 1),
(295600, 21196, 772, '<td valign="top">I think this photo is fairly weak in the challenge.  I see the colors, but they don''t play a large enough role in the image for me to consider it a strong entry for the ''primary colors'' competition...</td>', 'I think this photo is fairly weak in the challenge.  I see the colors, but they don''t play a large enough role in the image for me to consider it a strong entry for the ''primary colors'' competition...', '2003-05-12 12:33:23.000000', NULL, 1),
(295602, 20950, 772, '<td valign="top">interesting take on the challenge... I, personally, don''t like the interpretation *I* get from this photo :)</td>', 'interesting take on the challenge... I, personally, don''t like the interpretation *I* get from this photo :)', '2003-05-12 12:34:24.000000', NULL, 1),
(295605, 21173, 772, '<td valign="top">The focus here is a bit soft... i think a sharper image would have performed better :)</td>', 'The focus here is a bit soft... i think a sharper image would have performed better :)', '2003-05-12 12:35:13.000000', NULL, 1),
(295609, 21197, 7628, '<td valign="top">I do remember that pleasing smear of paint in art class - I always like how the colors ran together.  This subject is a good idea for the challenge.   It would work better with less black more color and having all of the paint in focus.</td>', 'I do remember that pleasing smear of paint in art class - I always like how the colors ran together.  This subject is a good idea for the challenge.   It would work better with less black more color and having all of the paint in focus.', '2003-05-12 12:39:37.000000', NULL, 1),
(295611, 21209, 7628, '<td valign="top">Nice texture and color.  Wish the fold inthe foreground was in focus too.</td>', 'Nice texture and color.  Wish the fold inthe foreground was in focus too.', '2003-05-12 12:40:50.000000', NULL, 1),
(295612, 21144, 7628, '<td valign="top">They are inside an invisible glass?!  Very primary colors.  I''d like to see a little more even lighting and composition - more push pins, more red visible.</td>', 'They are inside an invisible glass?!  Very primary colors.  I''d like to see a little more even lighting and composition - more push pins, more red visible.', '2003-05-12 12:43:15.000000', NULL, 1),
(295620, 21197, 5391, '<td valign="top">One of my outtakes was similar to this!  Very good!</td>', 'One of my outtakes was similar to this!  Very good!', '2003-05-12 12:48:02.000000', NULL, 1),
(295623, 21127, 5391, '<td valign="top">Really awesome - good graphic abstract composition.  I''d love to have seen a yellow one included also, somehow.</td>', 'Really awesome - good graphic abstract composition.  I''d love to have seen a yellow one included also, somehow.', '2003-05-12 12:50:36.000000', NULL, 1),
(295629, 21208, 5391, '<td valign="top">This is the best of the ''playground'' shots I''ve seen yet.  Great composition.  Nice work.  9</td>', 'This is the best of the ''playground'' shots I''ve seen yet.  Great composition.  Nice work.  9', '2003-05-12 13:04:10.000000', NULL, 1),
(295630, 21221, 6900, '<td valign="top">I really love the composition of this shot - it''s like...unfinished business.  The colors are all 3 present, striking and honestly with the exception of a slightly blown out corner - well exposed.  Excellent shot. 10</td>', 'I really love the composition of this shot - it''s like...unfinished business.  The colors are all 3 present, striking and honestly with the exception of a slightly blown out corner - well exposed.  Excellent shot. 10', '2003-05-12 13:05:31.000000', NULL, 1),
(295631, 21213, 5391, '<td valign="top">Nice composition.  The diagonal line adds a good dynamic and makes it eye-catching.</td>', 'Nice composition.  The diagonal line adds a good dynamic and makes it eye-catching.', '2003-05-12 13:06:48.000000', NULL, 1),
(295634, 20986, 6954, '<td valign="top">I think this is GREAT! Perfect exposure and woderful clarity, texture, and detail.</td>', 'I think this is GREAT! Perfect exposure and woderful clarity, texture, and detail.', '2003-05-12 13:10:53.000000', NULL, 1),
(295643, 21212, 5391, '<td valign="top">Really great.  Fantastic composition, lighting, and good, true colors.  10</td>', 'Really great.  Fantastic composition, lighting, and good, true colors.  10', '2003-05-12 13:15:10.000000', NULL, 1),
(295644, 21204, 327, '<td valign="top">Pretty photo, good focus and composition. I like this.</td>', 'Pretty photo, good focus and composition. I like this.', '2003-05-12 13:15:54.000000', NULL, 1),
(295646, 21219, 1379, '<td valign="top">What a sweet little face!  I think I recognize this tyke from an earlier b/w challenge?  It''s very very cute.</td>', 'What a sweet little face!  I think I recognize this tyke from an earlier b/w challenge?  It''s very very cute.', '2003-05-12 13:16:16.000000', NULL, 1),
(295647, 21209, 327, '<td valign="top">Unique shot.</td>', 'Unique shot.', '2003-05-12 13:16:26.000000', NULL, 1),
(295648, 21053, 1379, '<td valign="top">How glorious!</td>', 'How glorious!', '2003-05-12 13:16:32.000000', NULL, 1),
(295649, 20962, 1379, '<td valign="top">So crisp, it almost hurts my eyes!  I love that brilliant red.</td>', 'So crisp, it almost hurts my eyes!  I love that brilliant red.', '2003-05-12 13:16:57.000000', NULL, 1),
(295650, 21187, 1379, '<td valign="top">Those petals look so delicate and lovely.  Nice job!</td>', 'Those petals look so delicate and lovely.  Nice job!', '2003-05-12 13:17:18.000000', NULL, 1),
(295651, 21204, 1379, '<td valign="top">You really captured a big scene!  It''s easy to imagine what it was like there.  I hope you enjoyed the show!</td>', 'You really captured a big scene!  It''s easy to imagine what it was like there.  I hope you enjoyed the show!', '2003-05-12 13:17:55.000000', NULL, 1),
(295652, 21220, 1379, '<td valign="top">How random but wonderful!  Those three Y''s are really interesting.</td>', 'How random but wonderful!  Those three Y''s are really interesting.', '2003-05-12 13:18:22.000000', NULL, 1),
(295653, 21099, 1379, '<td valign="top">Nice context, not just another random colors shot.</td>', 'Nice context, not just another random colors shot.', '2003-05-12 13:18:44.000000', NULL, 1),
(295655, 21115, 327, '<td valign="top">creative....just unique as it gets......! Not crazy for the knife name/or reflections on the counter. Still this is a strong shot. Really good.</td>', 'creative....just unique as it gets......! Not crazy for the knife name/or reflections on the counter. Still this is a strong shot. Really good.', '2003-05-12 13:18:48.000000', NULL, 1),
(295657, 21174, 1379, '<td valign="top">Making keychains, eh?  I like it!</td>', 'Making keychains, eh?  I like it!', '2003-05-12 13:19:03.000000', NULL, 1),
(295658, 21185, 1379, '<td valign="top">The good ''n cheap brand!  Everyone loves wet ''n wild!</td>', 'The good ''n cheap brand!  Everyone loves wet ''n wild!', '2003-05-12 13:19:24.000000', NULL, 1),
(295659, 21099, 327, '<td valign="top">nice composition, just would of brought the dark cork forward ...that''s just me- too tight of a crop on the left but that''s minor.... IT''S a good entry all around.</td>', 'nice composition, just would of brought the dark cork forward ...that''s just me- too tight of a crop on the left but that''s minor.... IT''S a good entry all around.', '2003-05-12 13:20:38.000000', NULL, 1),
(295660, 20890, 1379, '<td valign="top">What a little cutie!  That yellow of her jacket is really nice against the blue in the umbrella.</td>', 'What a little cutie!  That yellow of her jacket is really nice against the blue in the umbrella.', '2003-05-12 13:20:50.000000', NULL, 1),
(295697, 21195, 772, '<td valign="top">excellent primary color shot... I think it would have been even stronger as a vertical shot which would have allowed you to not be ''dead centered'' and fill more of the frame...</td>', 'excellent primary color shot... I think it would have been even stronger as a vertical shot which would have allowed you to not be ''dead centered'' and fill more of the frame...', '2003-05-12 13:56:44.000000', NULL, 1),
(295698, 20948, 772, '<td valign="top">excellent abstract... I think a tad more light and a tad more sharpness would set this in motion nicely :)</td>', 'excellent abstract... I think a tad more light and a tad more sharpness would set this in motion nicely :)', '2003-05-12 13:57:19.000000', NULL, 1),
(295699, 21183, 7607, '<td valign="top">Looks somewhat over sharp or processed</td>', 'Looks somewhat over sharp or processed', '2003-05-12 13:58:05.000000', NULL, 1),
(295700, 21203, 772, '<td valign="top">This is an interesting shot, but the saturation of the colors seems a bit overpowering for my taste...</td>', 'This is an interesting shot, but the saturation of the colors seems a bit overpowering for my taste...', '2003-05-12 13:58:39.000000', NULL, 1),
(295702, 21181, 7607, '<td valign="top">Well focused and beautiful color.7</td>', 'Well focused and beautiful color.7', '2003-05-12 14:06:55.000000', NULL, 1),
(295705, 20950, 7607, '<td valign="top">Nicely done. Seems like sunshine changing the colors. Maybe too much yellow but I like it.</td>', 'Nicely done. Seems like sunshine changing the colors. Maybe too much yellow but I like it.', '2003-05-12 14:11:04.000000', NULL, 1),
(295707, 21101, 7607, '<td valign="top">Nice focus. My painted tulips have all gone past. Darn!</td>', 'Nice focus. My painted tulips have all gone past. Darn!', '2003-05-12 14:15:48.000000', NULL, 1),
(295709, 20996, 5391, '<td valign="top">Good idea - very creative.  A bit more color saturation would improve this, but overall I like this very much!</td>', 'Good idea - very creative.  A bit more color saturation would improve this, but overall I like this very much!', '2003-05-12 14:16:36.000000', NULL, 1),
(295712, 21194, 8488, '<td valign="top">This is almost great. I know it was a difficult shot, but just a little bit crisper, more in focus, and I could have given it two more points. It''s just blurry enough to make me feel I have to adjust my glasses (though of course that wouldn''t help). If it was a far/shaky shot, you could have gotten some sharpness by losing a little size, and improved the image immeasurably.</td>', 'This is almost great. I know it was a difficult shot, but just a little bit crisper, more in focus, and I could have given it two more points. It''s just blurry enough to make me feel I have to adjust my glasses (though of course that wouldn''t help). If it was a far/shaky shot, you could have gotten some sharpness by losing a little size, and improved the image immeasurably.', '2003-05-12 14:23:13.000000', NULL, 1),
(295714, 20870, 8488, '<td valign="top">Nice color, nice light, nice focus. I could have graded it a little higher if there were more contrast in it - when I sit back and squint slightly I see a morass of almost all exactly the same shade of yellow (which, while an accomplishment of sorts, doesn''t add to the visual interest much). 7 ... but might have been 8 or 9.</td>', 'Nice color, nice light, nice focus. I could have graded it a little higher if there were more contrast in it - when I sit back and squint slightly I see a morass of almost all exactly the same shade of yellow (which, while an accomplishment of sorts, doesn''t add to the visual interest much). 7 ... but might have been 8 or 9.', '2003-05-12 14:25:39.000000', NULL, 1),
(295716, 21084, 7801, '<td valign="top">Seen this type of thing so many times, well executed though.</td>', 'Seen this type of thing so many times, well executed though.', '2003-05-12 14:27:25.000000', NULL, 1),
