(296475, 20998, 3290, '<td valign="top">Great effect. Well done.</td>', 'Great effect. Well done.', '2003-05-13 11:29:59.000000', NULL, 1),
(296476, 21022, 472, '<td valign="top">focus and white balance</td>', 'focus and white balance', '2003-05-13 11:30:04.000000', NULL, 1),
(296477, 21142, 3290, '<td valign="top">Nice. But is that a piece of magic tape holding them together? Whatever it is, it spoils the shot. Perhaps blu-tack between them would have worked?</td>', 'Nice. But is that a piece of magic tape holding them together? Whatever it is, it spoils the shot. Perhaps blu-tack between them would have worked?', '2003-05-13 11:30:49.000000', NULL, 1),
(296479, 21203, 3290, '<td valign="top">Very vivid colours. Another simple but effective composition.</td>', 'Very vivid colours. Another simple but effective composition.', '2003-05-13 11:31:18.000000', NULL, 1),
(296481, 21144, 472, '<td valign="top">cool, but soft focus</td>', 'cool, but soft focus', '2003-05-13 11:32:10.000000', NULL, 1),
(296482, 20626, 3290, '<td valign="top">Wow! I really like this. I''d like to see it with the bright area cropped out (blue vase right up against the border).</td>', 'Wow! I really like this. I''d like to see it with the bright area cropped out (blue vase right up against the border).', '2003-05-13 11:32:49.000000', NULL, 1),
(296483, 21215, 472, '<td valign="top">a 10.</td>', 'a 10.', '2003-05-13 11:32:55.000000', NULL, 1),
(296484, 21208, 3290, '<td valign="top">Good composition.</td>', 'Good composition.', '2003-05-13 11:33:02.000000', NULL, 1),
(296485, 20851, 472, '<td valign="top">score would be higher were focus sharper</td>', 'score would be higher were focus sharper', '2003-05-13 11:33:08.000000', NULL, 1),
(296487, 20950, 472, '<td valign="top">good flag shot but i dont think the yellow works on a flag..</td>', 'good flag shot but i dont think the yellow works on a flag..', '2003-05-13 11:34:02.000000', NULL, 1),
(296514, 21149, 3290, '<td valign="top">The colours are great and I like the idea, but the composition is off - I''d crop out some of the empty space on the right. I also find myself wanting to see the ends of the plait.</td>', 'The colours are great and I like the idea, but the composition is off - I''d crop out some of the empty space on the right. I also find myself wanting to see the ends of the plait.', '2003-05-13 12:03:00.000000', NULL, 1),
(296521, 21195, 472, '<td valign="top">cool shot. i would have tried to fill the frame more with the subject.  failing that, put that whole building thing ''off-center''.</td>', 'cool shot. i would have tried to fill the frame more with the subject.  failing that, put that whole building thing ''off-center''.', '2003-05-13 12:24:09.000000', NULL, 1),
(296540, 20997, 7628, '<td valign="top">Is that a ferocious fanged critter behind those bars?  Primary colors and primary (school) imagination.  Very engaging.</td>', 'Is that a ferocious fanged critter behind those bars?  Primary colors and primary (school) imagination.  Very engaging.', '2003-05-13 12:47:31.000000', NULL, 1),
(296542, 21127, 7628, '<td valign="top">great color, but a little too abstract for me.</td>', 'great color, but a little too abstract for me.', '2003-05-13 12:48:05.000000', NULL, 1),
(296548, 21085, 7628, '<td valign="top">cute image, and I like the double meaning primary colors and frist steps into long friendships.  I also like the sunlight on thier hair</td>', 'cute image, and I like the double meaning primary colors and frist steps into long friendships.  I also like the sunlight on thier hair', '2003-05-13 12:51:01.000000', NULL, 1),
(296555, 21084, 7628, '<td valign="top">Well executed, and a good source of red, blue and yellow.  But I''ve seen the water drop idea before, and I''m sad (very sad!) to say, truly tired of the American flag</td>', 'Well executed, and a good source of red, blue and yellow.  But I''ve seen the water drop idea before, and I''m sad (very sad!) to say, truly tired of the American flag', '2003-05-13 12:55:11.000000', NULL, 1),
(296593, 21215, 7628, '<td valign="top">I like the gradual shift of blue in the sky and the arrow - both move you toward the moon.  Creative primary color find!</td>', 'I like the gradual shift of blue in the sky and the arrow - both move you toward the moon.  Creative primary color find!', '2003-05-13 13:18:04.000000', NULL, 1),
(296594, 20671, 1379, '<td valign="top">Great photo.  I was a Peace Corps Volunteer in SA, so this looks very very familiar.  What sweet little children, holding that barbed wire.  Powerful photograph.</td>', 'Great photo.  I was a Peace Corps Volunteer in SA, so this looks very very familiar.  What sweet little children, holding that barbed wire.  Powerful photograph.', '2003-05-13 13:25:38.000000', NULL, 1),
(296623, 20947, 6565, '<td valign="top">DOF really works for you here -- it makes the blocks seem so majestic and important (and huge!)  I like this photo a lot!</td>', 'DOF really works for you here -- it makes the blocks seem so majestic and important (and huge!)  I like this photo a lot!', '2003-05-13 14:09:36.000000', NULL, 1),
(296629, 20998, 772, '<td valign="top">good work with the color and the refraction in this image... i like your theme quite a bit... the only minor issue i have is the halos around the glass... I dunno if its coming from saturation or sharpening...</td>', 'good work with the color and the refraction in this image... i like your theme quite a bit... the only minor issue i have is the halos around the glass... I dunno if its coming from saturation or sharpening...', '2003-05-13 14:10:59.000000', NULL, 1),
(296642, 21004, 772, '<td valign="top">beautiful composition and color... the detail here is phenomenal... great work :)</td>', 'beautiful composition and color... the detail here is phenomenal... great work :)', '2003-05-13 14:16:27.000000', NULL, 1),
(296644, 21118, 772, '<td valign="top">excellent work and very unique idea...</td>', 'excellent work and very unique idea...', '2003-05-13 14:17:03.000000', NULL, 1),
(296651, 21221, 772, '<td valign="top">interesting use of color... the box looks like it is floating in space... no visible surface seems a bit odd in a photo like this...</td>', 'interesting use of color... the box looks like it is floating in space... no visible surface seems a bit odd in a photo like this...', '2003-05-13 14:21:09.000000', NULL, 1),
(296710, 20626, 772, '<td valign="top">excellent abstract... the smooth texture and color scheme in this photo work well for the challenge... the high key background also sets off the blue nicely... great work :) = 10 - setzler</td>', 'excellent abstract... the smooth texture and color scheme in this photo work well for the challenge... the high key background also sets off the blue nicely... great work :) = 10 - setzler', '2003-05-13 15:04:07.000000', NULL, 1),
(296714, 21146, 772, '<td valign="top">great photo... i can''t really explain it, but this is one of my favs in this challenge...  10 - setzler</td>', 'great photo... i can''t really explain it, but this is one of my favs in this challenge...  10 - setzler', '2003-05-13 15:04:40.000000', NULL, 1),
(296728, 21089, 772, '<td valign="top">very nice composition... the color saturation could be just a bit heavy, but excellent work :) - setzler</td>', 'very nice composition... the color saturation could be just a bit heavy, but excellent work :) - setzler', '2003-05-13 15:09:55.000000', NULL, 1),
