(300034, 20769, 5728, '<td valign="top">This is one killer shot! It gives the impression the sky is made of tulips, I like it.</td>', 'This is one killer shot! It gives the impression the sky is made of tulips, I like it.', '2003-05-16 10:45:41.000000', NULL, 1),
(300036, 21112, 5728, '<td valign="top">Please tell me what this is, I just can''t work it out. The effect is very successful, those colors are so vibrant. Good work.</td>', 'Please tell me what this is, I just can''t work it out. The effect is very successful, those colors are so vibrant. Good work.', '2003-05-16 10:47:36.000000', NULL, 1),
