(300053, 21071, 5728, '<td valign="top">Interesting set up. Effective too, so simple!</td>', 'Interesting set up. Effective too, so simple!', '2003-05-16 11:04:56.000000', NULL, 1),
(300064, 21098, 5728, '<td valign="top">Oh no it''s the blob!  Well done Salvador Dali :-) Your style was always one of my favourites and looking at this masterpiece, still is - Gary.</td>', 'Oh no it''s the blob!  Well done Salvador Dali :-) Your style was always one of my favourites and looking at this masterpiece, still is - Gary.', '2003-05-16 11:13:00.000000', NULL, 1),
(300065, 20962, 5728, '<td valign="top">Beautiful colors, good cropping. Maybe a tad on the dark side but I still like it.</td>', 'Beautiful colors, good cropping. Maybe a tad on the dark side but I still like it.', '2003-05-16 11:14:06.000000', NULL, 1),
(300068, 21196, 5728, '<td valign="top">Original for sure, and a top capture - 7.</td>', 'Original for sure, and a top capture - 7.', '2003-05-16 11:14:57.000000', NULL, 1),
