(300083, 21217, 1280, '<td valign="top">I like it!</td>', 'I like it!', '2003-05-16 11:26:02.000000', NULL, 1),
(300099, 21099, 5728, '<td valign="top">The lighting is very effective. Everything is fully in focus, very good. You should get this one ready for DPCprints.</td>', 'The lighting is very effective. Everything is fully in focus, very good. You should get this one ready for DPCprints.', '2003-05-16 11:42:12.000000', NULL, 1),
(300111, 21220, 5728, '<td valign="top">Good! Reminds me of my yellow submission, I did something similar with some bits of cheese hanging on a line, have a look. It didn''t do as well as I expected though. I hope yours does, I like the way you have set it up particularly the way each zipper is open at different lengths. Part of the line is showing in the top left hand corner,  I had the same problem :-) Good luck!</td>', 'Good! Reminds me of my yellow submission, I did something similar with some bits of cheese hanging on a line, have a look. It didn''t do as well as I expected though. I hope yours does, I like the way you have set it up particularly the way each zipper is open at different lengths. Part of the line is showing in the top left hand corner,  I had the same problem :-) Good luck!', '2003-05-16 11:49:41.000000', NULL, 1),
(300113, 21185, 5728, '<td valign="top">This is an excellent photo, well done you deserve a top score!</td>', 'This is an excellent photo, well done you deserve a top score!', '2003-05-16 11:50:18.000000', NULL, 1),
(300130, 21180, 5728, '<td valign="top">Such vibrant colors, this is a very good depiction of primary colors, amazing detail especially in the yellow paint.</td>', 'Such vibrant colors, this is a very good depiction of primary colors, amazing detail especially in the yellow paint.', '2003-05-16 12:02:43.000000', NULL, 1),
(300132, 21204, 5728, '<td valign="top">Choice concert shot! You got all the colors needed. Who is the band?</td>', 'Choice concert shot! You got all the colors needed. Who is the band?', '2003-05-16 12:03:59.000000', NULL, 1),
(300136, 21181, 5728, '<td valign="top">Incredible! You have given this flower a dreamy effect but at the same time kept all the sharpness, now that''s good work!</td>', 'Incredible! You have given this flower a dreamy effect but at the same time kept all the sharpness, now that''s good work!', '2003-05-16 12:08:17.000000', NULL, 1),
(300137, 20967, 5728, '<td valign="top">Good stuff! I particularly like the natural framing.</td>', 'Good stuff! I particularly like the natural framing.', '2003-05-16 12:09:17.000000', NULL, 1),
(300140, 21202, 5728, '<td valign="top">It took me a few seconds to figure out what this is but I got it :-) The perspective is great. What a pity the flag was in shadow or else the colors would really have come out well.</td>', 'It took me a few seconds to figure out what this is but I got it :-) The perspective is great. What a pity the flag was in shadow or else the colors would really have come out well.', '2003-05-16 12:16:29.000000', NULL, 1),
(300142, 20952, 5728, '<td valign="top">That was a lucky find! You''ve got a good eye!</td>', 'That was a lucky find! You''ve got a good eye!', '2003-05-16 12:17:14.000000', NULL, 1),
(300143, 21064, 5728, '<td valign="top">Those reds have come out well, deep and crispy!</td>', 'Those reds have come out well, deep and crispy!', '2003-05-16 12:18:00.000000', NULL, 1),
(300151, 21207, 5728, '<td valign="top">A simple shot, the choice of background enhances the image more than just a pure colored background would.</td>', 'A simple shot, the choice of background enhances the image more than just a pure colored background would.', '2003-05-16 12:27:01.000000', NULL, 1),
(300153, 21118, 5728, '<td valign="top">This image gives me a feeling of serenity. I like the stillness, good capture.</td>', 'This image gives me a feeling of serenity. I like the stillness, good capture.', '2003-05-16 12:27:59.000000', NULL, 1),
(300156, 21190, 5728, '<td valign="top">A Ferrari fan? It isn''t a "wow" photo but it has charachter. If you had the whole pic lighter without the shadows at the top right and bottom left it would have come across more effectively.</td>', 'A Ferrari fan? It isn''t a "wow" photo but it has charachter. If you had the whole pic lighter without the shadows at the top right and bottom left it would have come across more effectively.', '2003-05-16 12:30:33.000000', NULL, 1),
(300160, 21130, 5728, '<td valign="top">Wow, very psychedelic! You''ve created an interesting effect here. Good luck with this.</td>', 'Wow, very psychedelic! You''ve created an interesting effect here. Good luck with this.', '2003-05-16 12:37:53.000000', NULL, 1),
(300161, 21099, 675, '<td valign="top">damn fine composition, best ever on this site</td>', 'damn fine composition, best ever on this site', '2003-05-16 12:38:34.000000', NULL, 1),
(300162, 21108, 5728, '<td valign="top">You got all the colors here and it looks very dreamy. There is a kind of halo around the yellow flowers as if they are glowing.</td>', 'You got all the colors here and it looks very dreamy. There is a kind of halo around the yellow flowers as if they are glowing.', '2003-05-16 12:39:02.000000', NULL, 1),
(300166, 21173, 5728, '<td valign="top">This is an ideal subject for the primary color challenge. I would personally have used a different background to enhance the transporter, maybe something without texture. Somehow the bricks are a little distracting. Good luck anyway.</td>', 'This is an ideal subject for the primary color challenge. I would personally have used a different background to enhance the transporter, maybe something without texture. Somehow the bricks are a little distracting. Good luck anyway.', '2003-05-16 12:42:52.000000', NULL, 1),
(300169, 21170, 5728, '<td valign="top">Choice macro, the colors come through very well.</td>', 'Choice macro, the colors come through very well.', '2003-05-16 12:43:59.000000', NULL, 1),
(300170, 20998, 8760, '<td valign="top">Great Idea</td>', 'Great Idea', '2003-05-16 12:44:15.000000', NULL, 1),
(300171, 21133, 5728, '<td valign="top">Good one! Did you use a star filter here? The effect is very good!</td>', 'Good one! Did you use a star filter here? The effect is very good!', '2003-05-16 12:44:39.000000', NULL, 1),
(300172, 21095, 5728, '<td valign="top">Top macro shot. Very sharp and detailed. The shallow DOF works!</td>', 'Top macro shot. Very sharp and detailed. The shallow DOF works!', '2003-05-16 12:45:18.000000', NULL, 1),
