(300177, 20997, 5728, '<td valign="top">What is this? It has turned out well whatever it is, the shallow DOF creates a decent effect with the reds and blues in the background.</td>', 'What is this? It has turned out well whatever it is, the shallow DOF creates a decent effect with the reds and blues in the background.', '2003-05-16 12:51:42.000000', NULL, 1),
(300179, 21197, 5728, '<td valign="top">Good use of negative space. The black is a little spotty though.</td>', 'Good use of negative space. The black is a little spotty though.', '2003-05-16 12:52:39.000000', NULL, 1),
(300181, 20949, 5728, '<td valign="top">Good depiction of primary colors. The background seems a little busy, maybe a shallower DOF might have reduced that a little.</td>', 'Good depiction of primary colors. The background seems a little busy, maybe a shallower DOF might have reduced that a little.', '2003-05-16 12:57:29.000000', NULL, 1),
(300182, 21208, 5728, '<td valign="top">Good composition, you got the lighting bang on here!</td>', 'Good composition, you got the lighting bang on here!', '2003-05-16 12:58:57.000000', NULL, 1),
(300184, 21115, 5728, '<td valign="top">A blue capsicum! Well done, tell me how you did it......</td>', 'A blue capsicum! Well done, tell me how you did it......', '2003-05-16 13:04:41.000000', NULL, 1),
(300295, 21071, 7711, '<td valign="top">I like the detail on the pottery and the simple composition. its very effective.</td>', 'I like the detail on the pottery and the simple composition. its very effective.', '2003-05-16 14:41:15.000000', NULL, 1),
(300298, 21213, 7711, '<td valign="top">snot sure why your border looks totally unbalanced, I think it was a save/upload problem maybe. I like the detail of the textures on the balls. I think the background is a little TOO colourful to keep full attention on the tennis balls, but I really like the composition, the saturation of colours and the crop.</td>', 'snot sure why your border looks totally unbalanced, I think it was a save/upload problem maybe. I like the detail of the textures on the balls. I think the background is a little TOO colourful to keep full attention on the tennis balls, but I really like the composition, the saturation of colours and the crop.', '2003-05-16 14:43:48.000000', NULL, 1),
(300299, 21118, 7711, '<td valign="top">This is a very strange composition, but I really like it. Its like a meeting of friends. I think I might have included less of the water, and cropped to keep attention on the three colour elements, but a great shot nonetheless. 8</td>', 'This is a very strange composition, but I really like it. Its like a meeting of friends. I think I might have included less of the water, and cropped to keep attention on the three colour elements, but a great shot nonetheless. 8', '2003-05-16 14:45:36.000000', NULL, 1),
(300304, 21212, 7711, '<td valign="top">I like that this shot is like chaos, but each colour has it own distinct edges, without any blending into the other colours. Those lines really make this shot pop for me. There lis a little big of compression or something jaggies along the yellow pain near the bottle and I would have liked it if the yellow bottle itself were in focus too, perhaps a great DOF to capture it all? :) Great composition.</td>', 'I like that this shot is like chaos, but each colour has it own distinct edges, without any blending into the other colours. Those lines really make this shot pop for me. There lis a little big of compression or something jaggies along the yellow pain near the bottle and I would have liked it if the yellow bottle itself were in focus too, perhaps a great DOF to capture it all? :) Great composition.', '2003-05-16 14:48:13.000000', NULL, 1),
(300306, 20948, 7711, '<td valign="top">I would have liked a little more light on the curved to bring out more colour, but great composition and I like the negative space up to the left. 8</td>', 'I would have liked a little more light on the curved to bring out more colour, but great composition and I like the negative space up to the left. 8', '2003-05-16 14:49:08.000000', NULL, 1),
(300309, 21144, 7711, '<td valign="top">could have benefitted from "tack sharp" focus.. (sorry, couldn''t resist the pun!) and just a tad more light under the pushpins to bring out a little more of their colour.</td>', 'could have benefitted from "tack sharp" focus.. (sorry, couldn''t resist the pun!) and just a tad more light under the pushpins to bring out a little more of their colour.', '2003-05-16 14:52:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(300333, 21130, 2553, '<td valign="top">This photo looks very "washed out" to me.  I''m not crazy about the way the clouds and the sky look - there is not enough contrast, and really nothing to catch my eye, nothing dramatic, and the photo has very little impact for me.  I just don''t like this treatment for this challenge.</td>', 'This photo looks very "washed out" to me.  I''m not crazy about the way the clouds and the sky look - there is not enough contrast, and really nothing to catch my eye, nothing dramatic, and the photo has very little impact for me.  I just don''t like this treatment for this challenge.', '2003-05-16 15:20:54.000000', NULL, 1),
